#include <stdio.h>

/* parOuImpar le um inteiro digitado e imprime uma linha so: par ou impar.
   A leitura e o caminho do par ja estao escritos.
   Falta o outro caminho: o else que imprime impar. */
void parOuImpar(void) {
    int n = 0;

    scanf("%d", &n);

    if (n % 2 == 0) {
        printf("par\n");
    }
}

