    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    parOuImpar();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o 8 e par", linha, "par\n",
              "8 % 2 e 0: a condicao vale 1 e roda o bloco do if");
